  unfold BIGSHADOW_LO, BIGSHADOW_HI in KB6, KS6;
  change (hid (PSOIW.bptr I + PSOIW.bcap I <= 2147446784 \/ 17594333495296 <= PSOIW.bptr I)) in KB6; change (hid (PSOIW.sb I + PSOIW.scap I <= 2147446784 \/ 17594333495296 <= PSOIW.sb I)) in KS6;
