  lazymatch type of Hw with _ = Some (?p, ?e) =>
    pose proof (PSOIW.WSOME I p e Hw) as WS'; destruct WS' as (WP0E & WE0E & CHGE & INCo & CH1 & CH2 & WDEF & CHSH & PLE);
    assert (INC : In (PSOIW.ich I, 16384) (PSOIW.LB I)) by (unfold PSOIW.LB; apply in_or_app; right; exact INCo);
    lazymatch goal with [ WFT : CHA.wf_facts _ _ _ _ _ _ _ _, IBG : incl _ (PSOIW.LBG I) |- _ ] =>      (* [comment removed for export] *)
      pose proof (CHA.wf_blk _ _ _ _ _ _ _ _ WFT (PSOIW.ich I, 16384) (IBG _ INC)) as KCC; destruct KCC as ((KC0 & KC1 & KC16 & KC3 & KC4 & (KC5 & KC6 & KC7)) & KCdef & KCsha & KCbap & KCfap);
      cbn [fst snd] in KC0, KC1, KC16, KC3, KC4, KC5, KC6, KC7, KCdef, KCsha, KCbap, KCfap; unfold BIGSHADOW_LO, BIGSHADOW_HI in KC6;
      change (hid (PSOIW.ich I + 16384 <= 2147446784 \/ 17594333495296 <= PSOIW.ich I)) in KC6; pose proof (CHA.mod8_of_16 _ KC16) as KC8
    end
  end.

